WITH filtered_departments AS (SELECT * FROM departments WHERE budget <= 3903000), agg AS (SELECT dept_name, CASE WHEN budget >= 3061000 THEN 'high' WHEN budget >= 1441000 THEN 'mid' ELSE 'low' END AS budget_bucket, SUM(budget) AS total_budget FROM filtered_departments GROUP BY dept_name, CASE WHEN budget >= 3061000 THEN 'high' WHEN budget >= 1441000 THEN 'mid' ELSE 'low' END) SELECT * FROM agg ORDER BY budget_bucket
